private MaaJobStatus AbortCurrentTasker()
{
    // Recovery can detach the property concurrently with a user Stop.
    // Keep the same tasker alive for the null check and native Stop call.
    var tasker = MaaTasker;
    if (tasker == null)
        return MaaJobStatus.Succeeded;
    var status = tasker.Stop().Wait();

    return status;
}
